note = "# Actual first child of an ordinary owner prefix\n\n" + update + '\nThe final source has 203 lines and SHA256\ne790cbbaab2d2dd73a45738d950f45463102c2a7048f8bd59b5a95d6f3e965c6.\nThe sole public first_child header is byte-exact to the frozen 46-line plan.\nPrivate head inversion converts snoc Reached to a real first Step. Natural\nfuel inductions follow walk and row tails. Each skipped call keeps its exact\nreturn. The selected slot uses the same absolute index and take(slot) walk.\nThe ordinary body equation derives the SAME original source-row list.\n\nOriginal202 and prelaunch204 sources remain. Strict1 has four missing-name\nerrors. Dependent elimination removed next; the repair uses the surviving\nfuel and qualifies nodeEdges. Strict2 has 40 inference diagnostics at one\nuntyped entered binding. All headers, four term forms and the identical full\ncontext were reviewed. Inlining the same snoc/body_rows proof into the tuple\nsupplies its expected type. No mathematical premise or control witness\nchanges. Strict3 and root strict are literally empty.\n\nONE complete FULL has 3520979 bytes and SHA256\nbfe3af9863750dc5ef47ea3e407da6ed7dfab7e588918acef2ec319b2fbfdff4.\nComplete checked and printed types have 13609 identical non-whitespace\ncharacters. All eight settings are present. No public private predicate,\nproof omission or printer error appears. Axioms are propext,\nClassical.choice and Quot.sound. Four author commands contain the two\nfailed stricts. Root strict and Audit make six actual commands, two failed.\nAll launches retain fresh usage and effective max/high4GiB, swap0 and5m.\nThe independent review adds zero proof jobs and discloses prior authorship.\n\nThe frozen non-Top plan and its independent source challenge propose exact\nphysical child_reflect and same_child_payload_ne endpoints. They use the\nsame inherited relation on both finite quotient lists and remove its root\nclass. They assume no inherited fixedness, support closure, desired rank\nor caller-supplied reflection. The actual backwards positive law is stronger\nthan the public pair conclusion. Its existing producer is the SAME Required\nchronology pass; the actual consumer must retain it. Existing combine_covers\nalready supplies inherited coverage. No new resource oracle is needed.\n\nThe separate236-line geometry draft has selected strict/FULL checks. It is\nstaged for the next checkpoint. The approved56-line private enumeration was\nreduced to its used52 lines before checking; the unused helper and original\ndraft remain in zero-job history. Neither frozen plan is changed by those\nlater checks. Their manual algebra regeneration calculation remains unchecked\nand supplies no supported execution or nontermination counterexample.\n\nSuccessful supported model traversal with empty inherited constraints still\npreserves exactly the accepted finite terms. The whole-library target also\nrequires termination and each public Haskell specification from valid\nsupported INITIAL inputs. Prefix decomposition and immediate owner results\ndo not prove arbitrary ancestor exclusion, a finite fresh-request bound,\nall-call completion, final retention, repeated convergence or Haskell\ncorrespondence. All historical proofs/counterexamples remain. Goal active.\n'
documents = ['NEXT-PROMPT.md', 'HANDOFF.md', 'FINDINGS.md', 'lean/README.md',
             'lean/SYSTEM.md', 'lean/API-COVERAGE.md', 'lean/COVERAGE.md',
             'lean/notes-proof-status-20261017.md', 'lean/notes-current-system-claim.md']
for name in documents:
    original = subprocess.check_output(['git', 'show', start + ':' + name], cwd=ROOT, text=True)
    assert (ROOT / name).read_text() == original, name
    if name == 'FINDINGS.md':
        prefix = '# Current formalization findings\n\n## Haskell fix handoff for external work\n'
        marker = prefix + '\n' + (HERE / 'haskell-repair-index.md').read_text().rstrip() + '\n'
        assert original.startswith(marker)
        rest = original[len(marker):]
        assert rest.startswith('\n')
        changed = marker + '\n' + findings + '\n' + rest[1:]
        assert changed.replace(findings + '\n', '', 1) == original
    else:
        first, rest = original.split('\n', 1)
        changed = first + '\n\n' + update + rest
        assert changed.replace(update + '\n', '', 1) == original
    (ROOT / name).write_text(changed)
(HERE / 'current-update.md').write_text(update)
(HERE / 'findings-update.md').write_text(findings)
(ROOT / 'lean/notes-current-owner-prefix-decomposition.md').write_text(note)
print('Updated nine documents and focused note. All prior text remains.')
